In .NET MAUI Shell, you can handle this with two mechanisms:

### 1. Intercept back navigation with `OnNavigating`

```csharp
public partial class EditProductPage : ContentPage
{
    private bool _hasUnsavedChanges;
    private bool _allowNavigation;

    public EditProductPage()
    {
        InitializeComponent();
        Shell.SetBackButtonBehavior(this, new BackButtonBehavior
        {
            TextOverride = "Cancel",
            Command = new Command(async () => await ConfirmAndGoBack())
        });
    }

    protected override void OnAppearing()
    {
        base.OnAppearing();
        Shell.Current.Navigating += OnNavigating;
    }

    protected override void OnDisappearing()
    {
        base.OnDisappearing();
        Shell.Current.Navigating -= OnNavigating;
    }

    private async void OnNavigating(object sender, ShellNavigatingEventArgs e)
    {
        if (!_hasUnsavedChanges || _allowNavigation)
            return;

        // Defer navigation so we can show an async dialog
        var deferral = e.GetDeferral();
        bool leave = await DisplayAlert(
            "Unsaved Changes",
            "You have unsaved changes. Discard them?",
            "Discard", "Stay");

        if (leave)
            _allowNavigation = true;
        else
            e.Cancel();

        deferral.Complete();
    }

    private async Task ConfirmAndGoBack()
    {
        if (!_hasUnsavedChanges)
        {
            await Shell.Current.GoToAsync("..");
            return;
        }

        bool leave = await DisplayAlert(
            "Unsaved Changes",
            "You have unsaved changes. Discard them?",
            "Discard", "Stay");

        if (leave)
        {
            _allowNavigation = true;
            await Shell.Current.GoToAsync("..");
        }
    }
}
```

### Key points

- **`Shell.Navigating`** — fires on *any* navigation (back button, swipe, programmatic). Use `e.GetDeferral()` to pause it while awaiting the dialog, and `e.Cancel()` to block it.
- **`BackButtonBehavior`** — replaces the default back arrow. `TextOverride` sets the label; `Command` runs your custom logic instead of the default pop.
- **`_allowNavigation` flag** — prevents the `OnNavigating` handler from re-prompting after the user already confirmed via the custom button.

### XAML alternative for the back button

```xml
<Shell.BackButtonBehavior>
    <BackButtonBehavior TextOverride="Cancel"
                        Command="{Binding GoBackCommand}" />
</Shell.BackButtonBehavior>
```

> **Android hardware back**: On Android 13+, predictive back gesture may bypass `Shell.Navigating`. If that's an issue, set `android:enableOnBackInvokedCallback="false"` in `AndroidManifest.xml` or handle it via `OnBackPressed` in `MainActivity`.
